function compOptions(select, includeAll=false){
 const comps=state.competitions||[];
 const old=select.value;
 select.innerHTML=(includeAll?'<option value="">Todas</option>':'')+comps.map(c=>`<option value="${c.id}">${esc(c.name)} ${esc(c.season||'')}</option>`).join('');
 if(old && [...select.options].some(o=>o.value===old))select.value=old;
 else if(!includeAll&&comps.length)select.value=String(comps[0].id);
}
function teamOptions(select, compId, placeholder='Selecione'){
 const list=(state.teams||[]).filter(t=>t.active!==false&&(!compId||String(t.competitionId)===String(compId)));
 const old=select.value;
 select.innerHTML=`<option value="">${placeholder}</option>`+list.map(t=>`<option value="${t.id}">${esc(t.name)}${t.group?' • Grupo '+esc(t.group):''}</option>`).join('');
 if(list.some(t=>String(t.id)===old))select.value=old;
}
